      &lt;/sumario_nbo&gt;
      &lt;seccion num="1" nombre="I. Disposiciones generales"&gt;
         &lt;departamento nombre="MINISTERIO DE HACIENDA Y ADMINISTRACIONES PÚBLICAS"&gt;
            &lt;epigrafe nombre="Tabaco. Precios"&gt;
